package com.stocksentinel;
import com.stocksentinel.trend.TrendClient;import com.sun.net.httpserver.HttpServer;import com.fasterxml.jackson.databind.*;
import java.net.*;import java.nio.charset.StandardCharsets;import java.time.LocalDate;import java.util.*;import java.util.concurrent.CopyOnWriteArrayList;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class TrendClientTest {
    HttpServer server;ObjectMapper json=new ObjectMapper();List<String> paths=new CopyOnWriteArrayList<>();List<JsonNode> bodies=new CopyOnWriteArrayList<>();boolean fail;
    @BeforeEach void start()throws Exception{server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/internal/trend",e->{paths.add(e.getRequestURI().toString());var request=e.getRequestBody().readAllBytes();if(request.length>0)bodies.add(json.readTree(request));var data=(fail?"provider-credential-must-not-leak":"{\"key\":\"sh000300\"}").getBytes(StandardCharsets.UTF_8);e.getResponseHeaders().set("Content-Type","application/json");e.sendResponseHeaders(fail?502:200,data.length);e.getResponseBody().write(data);e.close();});server.start();}
    @AfterEach void stop(){server.stop(0);}
    TrendClient client(){return new TrendClient("http://127.0.0.1:"+server.getAddress().getPort());}
    @Test void quoteBatchUsesFixedInternalPathAndTypedKeys(){client().quotes(List.of("sh000300","sz000731"));assertEquals("/internal/trend/quotes",paths.getFirst());assertEquals("sh000300",bodies.getFirst().path("symbols").get(0).asText());}
    @Test void calculationAndIndexCarryExplicitDateAndConfirmation(){var client=client();var n=new java.math.BigDecimal("7.1234567890123456789");var bar=new com.stocksentinel.market.MarketContracts.Bar("000731",LocalDate.of(2025,10,20),n,n,n,n,n,n,null,com.stocksentinel.market.MarketContracts.Adjustment.NONE,"TEST",true);client.calculate("000731",List.of(bar),List.of(bar),false);client.index(LocalDate.of(2025,10,20),false);assertFalse(bodies.getFirst().path("current_day_confirmed").asBoolean());assertEquals("000731",bodies.getFirst().path("symbol").asText());var wire=bodies.getFirst().at("/raw/0");assertTrue(wire.path("trade_date").isTextual());assertEquals("2025-10-20",wire.path("trade_date").asText());assertTrue(wire.path("is_final").asBoolean());assertTrue(wire.path("close_price").isTextual());assertEquals(n.toPlainString(),wire.path("close_price").asText());assertEquals("NONE",wire.path("adjustment").asText());assertTrue(paths.getLast().contains("as_of=2025-10-20"));assertTrue(paths.getLast().contains("current_day_confirmed=false"));}
    @Test void providerErrorBodyDoesNotLeak(){fail=true;var error=assertThrows(IllegalStateException.class,()->client().quotes(List.of("sz000731")));assertEquals("TREND_QUOTES_UNAVAILABLE",error.getMessage());assertNull(error.getCause());assertFalse(error.toString().contains("credential"));}
    @Test void explicitIndexSelectionIsAllowlistedAndSentOverHttp(){var c=client();c.index(LocalDate.of(2025,10,20),true,"TENCENT");assertTrue(paths.getFirst().contains("source=TENCENT"));assertTrue(paths.getFirst().contains("current_day_confirmed=true"));assertThrows(IllegalArgumentException.class,()->c.index(LocalDate.of(2025,10,20),false,"UNTRUSTED"));assertEquals(1,paths.size());}
}
